func.func @main(%x: tensor<7x8xf32>) -> tensor<7x8xf32> {
  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<7x8xf32>

  // Constant 0.0 for reduce init
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Sum over dimension 1 (columns) to get sum_k exp(x[i, k]) for each row i
  %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<7x8xf32>, tensor<f32>) -> tensor<7xf32>

  // Broadcast sum_exp to shape (7,8) for division
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x8xf32>

  // Divide exp(x) by sum_k exp(x[i, k]) for softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_bcast : tensor<7x8xf32>

  return %softmax : tensor<7x8xf32>
}

module {
  func.func @main(
    %arg0: tensor<6x6x3x3x3xf32>,   // conv_transpose3d.weight [out_c, in_c, kD, kH, kW]
    %arg1: tensor<8x6x7x7x7xf32>    // input [N, in_c, D, H, W]
  ) -> tensor<8x6x9x9x9xf32> {
    // 1. Reverse kernel spatial dims for transposed convolution
    // PyTorch weight: [out_c, in_c, kD, kH, kW]
    // StableHLO expects kernel: [out_c, in_c, kD, kH, kW]
    // Reverse spatial dims: 2, 3, 4
    %rev_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

    // 2. Transposed convolution via stablehlo.convolution
    // Input: [N, in_c, D, H, W] = [8, 6, 7, 7, 7]
    // Kernel: [in_c, out_c, kD, kH, kW] = [6, 6, 3, 3, 3] (but StableHLO expects [out_c, in_c, ...])
    // Output: [N, out_c, D_out, H_out, W_out] = [8, 6, 9, 9, 9]
    // Stride: 1, Padding: 0, Output padding: 0
    // For transposed conv: lhs_dilation = stride = 1, rhs_dilation = 1, padding = 0

    // StableHLO dimension_numbers:
    //   input:   [b, f, 0, 1, 2]  (N, C, D, H, W)
    //   kernel:  [o, i, 0, 1, 2]  (out_c, in_c, kD, kH, kW)
    //   output:  [b, f, 0, 1, 2]  (N, out_c, D_out, H_out, W_out)
    // For transposed conv, swap in_c/out_c in kernel, but since both are 6, shape matches.

    // lhs_dilation = stride = 1, rhs_dilation = 1, window_strides = 1, padding = 0

    %result = "stablehlo.convolution"(%arg1, %rev_kernel) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, f, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x6x7x7x7xf32>, tensor<6x6x3x3x3xf32>) -> tensor<8x6x9x9x9xf32>

    return %result : tensor<8x6x9x9x9xf32>
  }
}

