  ) -> tensor<8x6x9x9x9xf32> {
    // 1. Reverse kernel spatial dims for transposed convolution
    // PyTorch weight: [out_c, in_c, kD, kH, kW]
    // StableHLO expects kernel: [out_c, in_c, kD, kH, kW]
    // Reverse spatial dims: 2, 3, 4
    %rev_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

    // For transposed convolution, set lhs_dilation = 1, rhs_dilation = 1, window_strides = 1,
    // but to get output shape 9, need to use padding = -1 (i.e., padding = [[-1, -1], [-1, -1], [-1, -1]])
    // See PyTorch ConvTranspose3d output shape formula:
    //   output = (input - 1) * stride - 2*padding + kernel_size + output_padding
    // For input=7, stride=1, padding=0, kernel=3, output_padding=0:
    //   (7-1)*1 - 0 + 3 + 0 = 6 + 3 = 9

    // In StableHLO, for transposed conv:
    //   output = lhs_dilation * (input_size - 1) + 1
    //            + padding_low + padding_high
    //            - rhs_dilation * (kernel_size - 1)
    // So, to get output=9:
    //   1*(7-1)+1 + pad_lo+pad_hi - 1*(3-1) = 6+1 + pad_lo+pad_hi - 2 = 7 + pad_lo+pad_hi - 2 = 5 + pad_lo+pad_hi
    // Set pad_lo+pad_hi = 4, so pad_lo=2, pad_hi=2

    // Therefore, use padding = [[2, 2], [2, 2], [2, 2]]

    %result = "stablehlo.convolution"(%arg1, %rev_kernel) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, f, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x6x7x7x7xf32>, tensor<6x6x3x3x3xf32>) -> tensor<8x6x9x9x9xf32>

    return %result : tensor<8x6x9x9x9xf32>
  }
}

