func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // We'll compute cumprod along dim=1 (the second dimension).
  // For each i in 0..5, output[:,i] = prod_{j=0}^i input[:,j]
  // We'll use reduce_window with a window that covers from 0 to i for each i, with window size = i+1 and stride=1.
  // But StableHLO's reduce_window only supports fixed window size, so we need to simulate cumprod by using a lower-triangular mask.

  // Step 1: Create a lower-triangular mask of shape (6,6), where mask[i,j]=1 if j<=i else 0
  // We'll use this mask to select, for each output position (i,j), the elements input[i,0]..input[i,j] for the product.

  // Create a constant mask tensor of shape (6,6,6), where mask[i,j,k]=1 if k<=j else 0, 0 otherwise.
  // For each output position (i,j), we want to multiply input[i,k] for k=0..j, so we need to broadcast input[i,k] to (i,j,k) and mask out k>j.

  // Step 2: Broadcast input to shape (6,6,6): input[i,k] -> input_broadcast[i,j,k] = input[i,k]
  %input_shape = "stablehlo.constant"() {value = dense<[6, 6, 6]> : tensor<3xi64>} : () -> tensor<3xi64>
  %input_expand = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 2>} : (tensor<6x6xf32>) -> tensor<6x6x6xf32>

  // Step 3: Create the lower-triangular mask of shape (6,6,6)
  // We'll do this by creating a tensor where mask[i,j,k]=1 if k<=j else 0
  // We'll create i, j, k index tensors and compare k <= j

  // Create i, j, k index tensors
  // First, create range tensors for each axis
  %i_range = "stablehlo.constant"() {value = dense<[0, 1, 2, 3, 4, 5]> : tensor<6xi32>} : () -> tensor<6xi32>
  %j_range = "stablehlo.constant"() {value = dense<[0, 1, 2, 3, 4, 5]> : tensor<6xi32>} : () -> tensor<6xi32>
  %k_range = "stablehlo.constant"() {value = dense<[0, 1, 2, 3, 4, 5]> : tensor<6xi32>} : () -> tensor<6xi32>

  // Broadcast i, j, k to (6,6,6)
  %i_b = "stablehlo.broadcast_in_dim"(%i_range) {broadcast_dimensions = array<i64: 0>} : (tensor<6xi32>) -> tensor<6x6x6xi32>
  %j_b = "stablehlo.broadcast_in_dim"(%j_range) {broadcast_dimensions = array<i64: 1>} : (tensor<6xi32>) -> tensor<6x6x6xi32>
  %k_b = "stablehlo.broadcast_in_dim"(%k_range) {broadcast_dimensions = array<i64: 2>} : (tensor<6xi32>) -> tensor<6x6x6xi32>

  // Compare k <= j
  %k_le_j = "stablehlo.compare"(%k_b, %j_b) {comparison_direction = #stablehlo<comparison_direction LE>} : (tensor<6x6x6xi32>, tensor<6x6x6xi32>) -> tensor<6x6x6xi1>

  // Convert mask to f32
  %mask_f32 = "stablehlo.convert"(%k_le_j) : (tensor<6x6x6xi1>) -> tensor<6x6x6xf32>

  // Step 4: Mask the input_broadcast
  %masked_input = "stablehlo.multiply"(%input_expand, %mask_f32) : (tensor<6x6x6xf32>, tensor<6x6x6xf32>) -> tensor<6x6x6xf32>

  // Step 5: For each output position (i,j), take the product over k (axis=2)
  // So reduce_window with window_dimensions = [1,1,6], window_strides=[1,1,1], padding=0, and use multiply as the reduction.
  // But we want to reduce over the full k axis for each (i,j), so we can use reduce_window or just reduce.

  // Use reduce over axis=2
  %init = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %cumprod = "stablehlo.reduce"(%masked_input, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %mul = "stablehlo.multiply"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%mul) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

  // The result is the cumprod along axis=1 for each row.
  return %cumprod : tensor<6x6xf32>
}

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // Implements cumprod along axis=1 using a scan pattern with reduce_window.
  // For each output[i, j], output[i, j] = prod_{k=0}^j input[i, k]

  // Step 1: Pad input on axis=1 with 1.0 at the left, so shape becomes (6,7)
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  // Pad: low=0, high=1 for axis=1
  %pad_config = "stablehlo.constant"() {value = dense<[[0, 0], [1, 0]]> : tensor<2x2xi64>} : () -> tensor<2x2xi64>
  %padded = "stablehlo.pad"(%arg0, %one) {padding = dense<[[0, 0], [1, 0]]> : tensor<2x2xi64>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 2: Use reduce_window with window_dimensions=[1, j+1], window_strides=[1,1], padding=0, and multiply as reduction
  // This will compute, for each output[i, j], the product of padded[i, j-(j):j+1] = input[i, 0:j+1]
  %init = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %cumprod = "stablehlo.reduce_window"(%padded, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %mul = "stablehlo.multiply"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%mul) : (tensor<f32>) -> ()
  }) {
    window_dimensions = array<i64: 1, 1>,
    window_strides = array<i64: 1, 1>,
    base_dilations = array<i64: 1, 1>,
    window_dilations = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Step 3: For each output[i, j], we want the product over input[i, 0:j], which is at cumprod[i, j+1]
  // So slice cumprod[:, 1:] to get shape (6,6)
  %start = "stablehlo.constant"() {value = dense<[0, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
  %limit = "stablehlo.constant"() {value = dense<[6, 7]> : tensor<2xi64>} : () -> tensor<2xi64>
  %stride = "stablehlo.constant"() {value = dense<[1, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
  %result = "stablehlo.slice"(%cumprod, %start, %limit, %stride) : (tensor<6x7xf32>, tensor<2xi64>, tensor<2xi64>, tensor<2xi64>) -> tensor<6x6xf32>

  return %result : tensor<6x6xf32>
}

func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // Implements cumprod along axis=1 using reduce_window.
  // For each output[i, j], output[i, j] = prod_{k=0}^j input[i, k]

