    // For transposed conv: set lhs_dilation = stride, rhs_dilation = 1, padding = kernel_size-1-padding, output_padding handled by padding
    // See PyTorch/ONNX/StableHLO conventions.
    // For transposed conv, use:
    //   window_strides = [1,1]
    //   lhs_dilation = [2,2] (stride)
    //   rhs_dilation = [1,1]
    //   padding = [[3,3],[3,3]] (kernel_size-1-padding = 4-1-1=2, but output_padding=1, so 2+1=3)
    //   dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1] (NCHW/OIHW/NCHW)
    //   feature_group_count = 1

    %conv = "stablehlo.convolution"(%arg3, %w_t) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[3, 3], [3, 3]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 2, 2>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

    // Add conv_transpose.bias: %arg2: [6]
    // Broadcast to [6,6,15,15] along feature dim (C_out)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x15x15xf32>
    %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x15x15xf32>

    // 2. Softmax along channel dim (dim=1)
    // For each [N, :, H, W], softmax along dim=1
    // Softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
