    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
    %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<6x6x15x15xf32>

