    }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>
    // Broadcast sum back to [6,6,15,15]
    %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>
    %softmax = stablehlo.divide %exp, %sum_broadcast : tensor<6x6x15x15xf32>

    // 3. Add bias: %arg0: [6,1,1] -> broadcast to [6,6,15,15] along dim 1
    %bias2_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>
    %add_bias = stablehlo.add %softmax, %bias2_broadcast : tensor<6x6x15x15xf32>

    // 4. Multiply by scaling factor (2.0)
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scaled = stablehlo.multiply %add_bias, %scale : tensor<6x6x15x15xf32>

    // 5. Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
    %neg = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
    %exp_neg = stablehlo.exponential %neg : tensor<6x6x15x15xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
    %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<6x6x15x15xf32>
    %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x6x15x15xf32>

    return %sigmoid : tensor<6x6x15x15xf32>
  }
}

module {
  func.func @main(
    %arg0: tensor<6x1x1xf32>,         // bias (for add after softmax)
    %arg1: tensor<7x6x4x4xf32>,       // conv_transpose.weight (OIHW)
    %arg2: tensor<6xf32>,             // conv_transpose.bias
    %arg3: tensor<6x7x7x7xf32>        // input (NCHW)
  ) -> tensor<6x6x15x15xf32> {
    // 1. Transposed convolution (ConvTranspose2d)
    // Input: %arg3: [N=6, C_in=7, H=7, W=7]
    // Weight: %arg1: [C_in=7, C_out=6, KH=4, KW=4] (PyTorch OIHW)
    // StableHLO expects: input [N, C_in, H, W], kernel [C_out, C_in, KH, KW]
    // So, transpose %arg1 from [7,6,4,4] to [6,7,4,4]
    %w_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

    // ConvTranspose2d: stride=2, padding=1, output_padding=1, kernel_size=4
    // For transposed conv: set lhs_dilation = stride, rhs_dilation = 1, padding = kernel_size-1-padding + output_padding
    //   window_strides = [1,1]
    //   lhs_dilation = [2,2] (stride)
    //   rhs_dilation = [1,1]
    //   padding = [[3,3],[3,3]] (kernel_size-1-padding + output_padding = 4-1-1+1 = 3)
    //   dimension_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1] (NCHW/OIHW/NCHW)
    //   feature_group_count = 1

    %conv = "stablehlo.convolution"(%arg3, %w_t) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[3, 3], [3, 3]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 2, 2>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

    // Add conv_transpose.bias: %arg2: [6]
    // Broadcast to [6,6,15,15] along feature dim (C_out)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x15x15xf32>
    %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x15x15xf32>

    // 2. Softmax along channel dim (dim=1)
    // For each [N, :, H, W], softmax along dim=1
    // Softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
    // Compute max along dim=1
    %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>
    %max = "stablehlo.reduce"(%conv_bias, %neg_inf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %m = stablehlo.maximum %a, %b : tensor<f32>
        "stablehlo.return"(%m) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>
    // Broadcast max back to [6,6,15,15] for subtraction
    %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>
    %centered = stablehlo.subtract %conv_bias, %max_broadcast : tensor<6x6x15x15xf32>
    %exp = stablehlo.exponential %centered : tensor<6x6x15x15xf32>
    // Sum exp along dim=1
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum_exp = "stablehlo.reduce"(%exp, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<f32>) -> tensor<6x15x15xf32>
    // Broadcast sum back to [6,6,15,15]
    %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<6x15x15xf32>) -> tensor<6x6x15x15xf32>
    %softmax = stablehlo.divide %exp, %sum_broadcast : tensor<6x6x15x15xf32>

    // 3. Add bias: %arg0: [6,1,1] -> broadcast to [6,6,15,15] along dim 1
    %bias2_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>
    %add_bias = stablehlo.add %softmax, %bias2_broadcast : tensor<6x6x15x15xf32>

    // 4. Multiply by scaling factor (2.0)
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
    %scaled = stablehlo.multiply %add_bias, %scale_broadcast : tensor<6x6x15x15xf32>

    // 5. Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
    %neg = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
    %exp_neg = stablehlo.exponential %neg : tensor<6x6x15x15xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
    %denom = stablehlo.add %one_broadcast, %exp_neg : tensor<6x6x15x15xf32>
    %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<6x6x15x15xf32>

    return %sigmoid : tensor<6x6x15x15xf32>
  }
}

