    // relu6(x) = min(max(x, 0), 6)
    %c3 = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    %c6 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %c0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

    // Broadcast constants to [6,16,13,4,4]
    %c3_b = "stablehlo.broadcast_in_dim"(%c3) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %c6_b = "stablehlo.broadcast_in_dim"(%c6) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
    %c0_b = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x16x13x4x4xf32>

    %x_plus_3 = stablehlo.add %conv_bias_add, %c3_b : tensor<6x16x13x4x4xf32>
    %relu6_1 = stablehlo.maximum %x_plus_3, %c0_b : tensor<6x16x13x4x4xf32>
    %relu6 = stablehlo.minimum %relu6_1, %c6_b : tensor<6x16x13x4x4xf32>
    %mul = stablehlo.multiply %conv_bias_add, %relu6 : tensor<6x16x13x4x4xf32>
    %hardswish = stablehlo.divide %mul, %c6_b : tensor<6x16x13x4x4xf32>

    // 3. GroupNorm: num_groups=4, num_channels=16
    // GroupNorm: for each group of 4 channels, normalize over [C//G, D, H, W] per batch
    // For each batch b, group g, compute mean/var over [4,13,4,4] for channels in group g
    // We'll reshape to [6,4,4,13,4,4] (B, G, C_per_G, D, H, W)
    %reshaped = stablehlo.reshape %hardswish : (tensor<6x16x13x4x4xf32>) -> tensor<6x4x4x13x4x4xf32>

    // Compute mean over [2,3,4,5] (C_per_G, D, H, W)
    // Reduce mean: sum then divide by N=4*13*4*4=832
    %c0f = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %sum = "stablehlo.reduce"(%reshaped, %c0f) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = dense<[2,3,4,5]> : tensor<4xi64>} : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>

    // Divide by 832 (number of elements per group)
    %c832 = "stablehlo.constant"() {value = dense<832.0> : tensor<f32>} : () -> tensor<f32>
    %mean = stablehlo.divide %sum, %c832 : tensor<6x4xf32>

    // Broadcast mean to [6,4,4,13,4,4]
    %mean_b = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>

    // Subtract mean
    %centered = stablehlo.subtract %reshaped, %mean_b : tensor<6x4x4x13x4x4xf32>

    // Compute variance: mean((x - mean)^2)
    %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x4x4x13x4x4xf32>
    %var_sum = "stablehlo.reduce"(%centered_sq, %c0f) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = dense<[2,3,4,5]> : tensor<4xi64>} : (tensor<6x4x4x13x4x4xf32>, tensor<f32>) -> tensor<6x4xf32>
    %var = stablehlo.divide %var_sum, %c832 : tensor<6x4xf32>

    // Add epsilon for numerical stability
    %eps = "stablehlo.constant"() {value = dense<1.0E-5> : tensor<f32>} : () -> tensor<f32>
    %var_eps = stablehlo.add %var, %eps : tensor<6x4xf32>

    // sqrt(var + eps)
    %var_eps_b = "stablehlo.broadcast_in_dim"(%var_eps) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>} : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>
    %std = stablehlo.sqrt %var_eps_b : tensor<6x4x4x13x4x4xf32>

    // Normalize
    %normed = stable

