}

func.func @main(
  %arg0: tensor<6x7x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
  %arg1: tensor<6xf32>,         // conv.bias [out_c]
  %arg2: tensor<6x7x6x6xf32>    // input [N, in_c, H, W]
) -> tensor<6x6x2x2xf32> {
  // --- Convolution ---
  // PyTorch Conv2d: input [N, C_in, H, W], weight [C_out, C_in, kH, kW], bias [C_out]
  // StableHLO: input [N, C_in, H, W], kernel [O, I, kH, kW], output [N, O, H_out, W_out]
  // Stride=1, Padding=0, Dilation=1, Groups=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    // Explicitly specify batch (b) and feature (f) dimensions
    // input:  [b, f, 0, 1] = [N, C_in, H, W]
    // kernel: [o, i, 0, 1] = [O, I, kH, kW]
    // output: [b, f, 0, 1] = [N, O, H_out, W_out]
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // --- Add bias ---
  // Bias shape: [6], output shape: [6, 6, 4, 4]
  // Broadcast bias to [6, 6, 4, 4] along dim 1 (feature dim)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // --- Subtract subtract1_value (0.5) ---
  %cst_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_sub1_broadcast = "stablehlo.broadcast_in_dim"(%cst_sub1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub1 = stablehlo.subtract %conv_bias, %cst_sub1_broadcast : tensor<6x6x4x4xf32>

  // --- Tanh activation ---
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // --- Subtract subtract2_value (0.2) ---
  %cst_sub2 = stablehlo.constant dense<0.2> : tensor<f32>
  %cst_sub2_broadcast = "stablehlo.broadcast_in_dim"(%cst_sub2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %sub2 = stablehlo.subtract %tanh, %cst_sub2_broadcast : tensor<6x6x4x4xf32>

  // --- AvgPool2d(kernel_size=2) ---
  // PyTorch default: stride=kernel_size, padding=0
  // Reduce window with window_dimensions=[1,1,2,2], window_strides=[1,1,2,2], padding=0
  // Reduce mean: sum / window_size (window_size=4)
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce_window"(%sub2, %cst_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    base_dilations = array<i64: 1, 1, 1, 1>,
    window_dilations = array<i64: 1, 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide by window size (4.0)
  %cst_four = stablehlo.constant dense<4.0> : tensor<f32>
  %cst_four_broadcast = "stablehlo.broadcast_in_dim"(%cst_four) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avg = stablehlo.divide %sum, %cst_four_broadcast : tensor<6x6x2x2xf32>

  return %avg : tensor<6x6x2x2xf32>
}

module {
  func.func @main(
    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias [out_c]
    %arg2: tensor<6x8x6x6xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x7x4x4xf32> {
    // 1. Convolution
    // PyTorch Conv2d: input [N, C_in, H, W], weight [C_out, C_in, kH, kW], bias [C_out]
    // StableHLO: NCHW (input), OIHW (weight), output NCHW
    // Output shape: [6, 7, 4, 4]
    // Stride=1, Padding=0, Dilation=1

    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, o, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // 2. Add bias: bias shape [7] -> broadcast to [6,7,4,4]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // 3. Divide by constant divisor=2
    %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
    %two_bcast = "stablehlo.broadcast_in_dim"(%cst_two) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %div = stablehlo.divide %biased, %two_bcast : tensor<6x7x4x4xf32>

    // 4. LeakyReLU: y = x if x >= 0 else 0.01 * x
    // Compute mask: x >= 0
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %ge_mask = "stablehlo.compare"(%div, %zero_bcast) {comparison_direction = #stablehlo<comparison_direction GE>} : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xi1>

    // Compute 0.01 * x
    %alpha = stablehlo.constant dense<0.01> : tensor<f32>
    %alpha_bcast = "stablehlo.broadcast_in_dim"(%alpha) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %mul_alpha = stablehlo.multiply %div, %alpha_bcast : tensor<6x7x4x4xf32>

    // Select: if ge_mask then x else 0.01*x
    %leaky = "stablehlo.select"(%ge_mask, %div, %mul_alpha) : (tensor<6x7x4x4xi1>, tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

    return %leaky : tensor<6x7x4x4xf32>
  }
}

