    ) -> tensor<16x6x5x5x10xf32> {
    // PyTorch nn.Conv3d with:
    //   in_channels = 3
    //   out_channels = 6
    //   kernel_size = (3, 3, 1)
    //   stride = 1
    //   padding = 0
    //   dilation = 1
    //   groups = 1
    //   bias = False

    // PyTorch input: (N, C_in, H, W, D)
    // PyTorch weight: (C_out, C_in, kH, kW, kD)
    // StableHLO expects:
    //   input: (N, C_in, H, W, D)
    //   kernel: (C_out, C_in, kH, kW, kD)
    //   output: (N, C_out, H_out, W_out, D_out)
    // So layouts match.

    // Convolution attributes:
    //   window_strides = [1, 1, 1] (stride=1)
    //   padding = [[0,0],[0,0],[0,0]] (no padding)
    //   lhs_dilation = [1,1,1] (no input dilation)
    //   rhs_dilation = [1,1,1] (no kernel dilation)
    //   dimension_numbers = [b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]
    //   feature_group_count = 1
    //   batch_group_count = 1

    %0 = "stablehlo.convolution"(%arg1, %arg0) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        o, i, 0, 1, 2
      ]->[
        b, f, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x3x7x7x10xf32>, tensor<6x3x3x3x1xf32>) -> tensor<16x6x5x5x10xf32>

