module {
  func.func @main(
    %arg0: tensor<7x7x3x3xf32>,   // conv_transpose.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv_transpose.bias   [out_c]
    %arg2: tensor<6x7x8x8xf32>    // input [N, in_c, H, W]
  ) -> tensor<6x7x1x1xf32> {
    // 1. Transposed convolution (ConvTranspose2d)
    // PyTorch: ConvTranspose2d(in_c=7, out_c=7, kernel=3, stride=1, padding=1)
    // StableHLO: lhs=input [N, in_c, H, W], rhs=weight [in_c, out_c, kH, kW] (need to permute to [out_c, in_c, kH, kW])
    // But PyTorch weight is [out_c, in_c, kH, kW], which matches StableHLO's OIHW for transposed conv.
    // For transposed conv, use lhs_dilation=stride, rhs_dilation=1, padding=kernel_size-1-padding
    // See: https://pytorch.org/docs/stable/generated/torch.nn.ConvTranspose2d.html

    // For stride=1, padding=1, kernel=3:
    // output_size = (input_size - 1) * stride - 2*padding + kernel_size
    //             = (8-1)*1 - 2*1 + 3 = 7 - 2 + 3 = 8
    // So output is 8x8, i.e. shape preserved.

    // For transposed conv in StableHLO:
    // - lhs=input: [N, in_c, H, W]
    // - rhs=weight: [out_c, in_c, kH, kW]
    // - dimension_numbers: [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
    // - lhs_dilation: stride (1,1)
    // - rhs_dilation: (1,1)
    // - padding: (kernel_size-1-padding, kernel_size-1-padding) = (1,1)
    // - feature_group_count: 1

    %0 = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x8x8xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x8x8xf32>

    // 2. Add bias: bias shape [7], output shape [6,7,8,8]
    // Broadcast bias to [6,7,8,8]
    %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x8x8xf32>
    %2 = stablehlo.add %0, %1 : tensor<6x7x8x8xf32>

    // 3. MaxPool2d(kernel=2, stride=2)
    // window_dimensions = [1,1,2,2], window_strides = [1,1,2,2], padding = 0
    %cst_minf = stablehlo.constant dense<0xFF800000> : tensor<f32>
    %3 = "stablehlo.reduce_window"(%2, %cst_minf) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %max = stablehlo.maximum %a, %b : tensor<f32>
        stablehlo.return %max : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 2, 2>,
      window_strides = array<i64: 1, 1, 2, 2>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7x4x4xf32>

    // 4. Hardtanh(min=-1, max=1): clamp between -1 and 1
    %cst_neg1 = stablehlo.constant dense<-1.0> : tensor<6x7x4x4xf32>
    %cst_pos1 = stablehlo.constant dense<1.0> : tensor<6x7x4x4xf32>
    %4 = stablehlo.maximum %3, %cst_neg1 : tensor<6x7x4x4xf32>
    %5 = stablehlo.minimum %4, %cst_pos1 : tensor<6x7x4x4xf32>

    // 5. Mean over spatial dims (2,3), keepdim=True
    // Reduce sum over dims 2,3, then divide by 16.0 (since 4x4 window)
    %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
    %6 = "stablehlo.reduce"(%5, %cst_zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
