func.func @main(
    %bias: tensor<16xf32>,                // arg0: bias for addition after Swish
    %matmul_weight: tensor<16x16xf32>,    // arg1: Linear weight (out_features x in_features)
    %matmul_bias: tensor<16xf32>,         // arg2: Linear bias
    %gn_weight: tensor<16xf32>,           // arg3: GroupNorm weight (gamma)
    %gn_bias: tensor<16xf32>,             // arg4: GroupNorm bias (beta)
    %x: tensor<16x16xf32>                 // arg5: input (batch_size x in_features)
) -> tensor<16x16xf32> {
  // 1. Linear: y = x @ W^T + b
  // x: [16,16], matmul_weight: [16,16] (out_features x in_features)
  // Need to do x @ matmul_weight^T, i.e. [16,16] x [16,16]^T = [16,16] x [16,16] = [16,16]
  // But PyTorch Linear expects weight as [out_features, in_features], so we need to transpose weight.

  // Transpose matmul_weight from [16,16] to [16,16] (no-op, but for clarity)
  // Actually, for dot_general, we want to contract last dim of x (in_features) with last dim of weight (in_features)
  // So, we can use dot_general with lhs_contracting=[1], rhs_contracting=[1]
  // But to get x @ W^T, we need to swap axes of weight, or set contracting dims accordingly.

  // So, transpose weight to [in_features, out_features] = [16,16]
  %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // Now, dot_general: x [16,16], weight_t [16,16], contract last dim of x (1) with first dim of weight_t (0)
  %linear = "stablehlo.dot_general"(%x, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add matmul_bias: [16] -> [16,16] (broadcast over batch)
  %matmul_bias_bcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %linear_bias = stablehlo.add %linear, %matmul_bias_bcast : tensor<16x16xf32>

  // 2. Swish activation: swish(x) = sigmoid(x) * x
  // sigmoid(x) = 1 / (1 + exp(-x))
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %neg_linear = stablehlo.negate %linear_bias : tensor<16x16xf32>
  %exp_neg_linear = stablehlo.exponential %neg_linear : tensor<16x16xf32>
  %exp_plus_one = stablehlo.add %exp_neg_linear, %one : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one, %exp_plus_one : tensor<16x16xf32>
  %swish = stablehlo.multiply %sigmoid, %linear_bias : tensor<16x16xf32>

  // 3. Add bias: [16] -> [16,16] (broadcast over batch)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_bcast : tensor<16x16xf32>

  // 4. GroupNorm(num_groups=16, num_channels=16, eps=1e-5)
  // GroupNorm with 16 groups and 16 channels: each channel is its own group.
  // So, normalization is per channel, over batch dimension.
  // For each channel c, mean/var over batch (axis 0), for all n in batch.

  // Compute mean over batch (axis 0): result shape [16]
  %mean_init = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%swish_bias, %mean_init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // Divide by batch size (16) to get mean
  %batch_size_f = stablehlo.constant dense<16.0> : tensor<f32>
  %mean = stablehlo.divide %mean, %batch_size_f : tensor<16xf32>

  // Broadcast mean to [16,16] for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Subtract mean
  %centered = stablehlo.subtract %swish_bias, %mean_bcast : tensor<16x16xf32>

  // Compute variance: mean((x - mean)^2) over batch
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<16x16xf32>
  %var = "stablehlo.reduce"(%centered_sq, %mean_init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.divide %var, %batch_size_f : tensor<16xf32>

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16xf32>

  // sqrt(var + eps)
  %std = stablehlo.sqrt %var_eps : tensor<16xf32>

  // Broadcast std to [16,16]
  %std_bcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Normalize
  %normed = stablehlo.divide %centered, %std_bcast : tensor<16x16xf32>

  // Apply scale (gamma) and shift (beta): both [16] -> [16,16]
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normed, %gn_weight_bcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<16x16xf32>

  return %shifted : tensor<16x16xf32>
}

