module {
  func.func @main(
    %arg0: tensor<6x7x3x3x3xf32>,   // conv_transpose3d.weight [in_c, out_c, kD, kH, kW]
    %arg1: tensor<8x6x8x8x8xf32>    // input [N, in_c, D, H, W]
  ) -> tensor<8x7x10x10x10xf32> {
    // 1. Reverse kernel spatial dims for transposed conv
    // PyTorch weight: [in_c, out_c, kD, kH, kW]
    // StableHLO expects: [out_c, in_c, kD, kH, kW]
    // So, transpose and reverse spatial dims

    // Transpose [in_c, out_c, kD, kH, kW] -> [out_c, in_c, kD, kH, kW]
    %w_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<6x7x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>
    // Reverse spatial dims (2,3,4)
    %w_rev = "stablehlo.reverse"(%w_t) {dimensions = array<i64: 2, 3, 4>} : (tensor<7x6x3x3x3xf32>) -> tensor<7x6x3x3x3xf32>

    // 2. Set up convolution parameters for transposed conv
    // Input: [N, in_c, D, H, W] = [8, 6, 8, 8, 8]
    // Kernel: [out_c, in_c, kD, kH, kW] = [7, 6, 3, 3, 3]
    // Output: [N, out_c, D_out, H_out, W_out] = [8, 7, 10, 10, 10]
    // Stride: 1, Padding: 0, Output_padding: 0, Dilation: 1

    // For transposed conv:
    // - lhs_dilation = stride = [1,1,1]
    // - rhs_dilation = dilation = [1,1,1]
    // - padding = [k-1, k-1] for each spatial dim (since padding=0 in PyTorch)
    //   (see PyTorch/ONNX/StableHLO transposed conv mapping)

    // For each spatial dim:
    //   padding = (kernel_size - 1) = 2
    //   so, padding = [[2,2],[2,2],[2,2]]

    // dimension_numbers:
    //   input:  [N, C, D, H, W] -> [b, f, 0, 1, 2]
    //   kernel: [O, I, kD, kH, kW] -> [o, i, 0, 1, 2]
    //   output: [N, O, D, H, W] -> [b, f, 0, 1, 2]
    //   #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>

    %result = "stablehlo.convolution"(%arg1, %w_rev) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
