    // StableHLO convolution: input [N, C_in, H, W], kernel [O, I, kH, kW]
    // Need to swap axes 0 and 1 of weight to get [O, I, kH, kW]
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<8x8x3x3xf32>) -> tensor<8x8x3x3xf32>

    // For transposed convolution, use lhs_dilation = stride, rhs_dilation = 1, and reverse kernel spatial dims
    // Reverse kernel spatial dims (axes 2 and 3)
    %weight_rev = "stablehlo.reverse"(%weight_t) {dimensions = array<i64: 2, 3>} : (tensor<8x8x3x3xf32>) -> tensor<8x8x3x3xf32>

    // lhs_dilation = [1, 1] (stride=1), rhs_dilation = [1, 1], window_strides = [1, 1], padding = [[0,0],[0,0]]
    // dimension_numbers: [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
    %conv = "stablehlo.convolution"(%arg4, %weight_rev) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x8x8x8xf32>, tensor<8x8x3x3xf32>) -> tensor<8x8x10x10xf32>

    // Add bias: bias shape [8] -> [1,8,1,1] -> [8,8,10,10]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<8xf32>) -> tensor<1x8x1x1xf32>
    %bias_bcast4 = "stablehlo.broadcast_in_dim"(%bias_bcast) {broadcast_dimensions = array<i64: 0,1,2,3>} : (tensor<1x8x1x1xf32>) -> tensor<8x8x10x10xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast4 : tensor<8x8x10x10xf32>

    // 2. GELU activation: GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
    %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %x_div_sqrt2 = stablehlo.divide %conv_bias, %sqrt2_bcast : tensor<8x8x10x10xf32>
    %erf = "chlo.erf"(%x_div_sqrt2) : (tensor<8x8x10x10xf32>) -> tensor<8x8x10x10xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %erf_plus1 = stablehlo.add %erf, %one_bcast : tensor<8x8x10x10xf32>
    %half = stablehlo.constant dense<0.5> : tensor<f32>
    %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %gelu_tmp = stablehlo.multiply %conv_bias, %erf_plus1 : tensor<8x8x10x10xf32>
    %gelu = stablehlo.multiply %gelu_tmp, %half_bcast : tensor<8x8x10x10xf32>

    // 3. GroupNorm (num_groups=8, num_channels=8): so each group is 1 channel
    // For each [N, C, H, W], group is C axis, so mean/var over [2,3] (H,W) for each N,C
    // Compute mean over H,W (axes 2,3)
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %mean = "stablehlo.reduce"(%gelu, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2, 3>} : (tensor<8x8x10x10xf32>, tensor<f32>) -> tensor<8x8xf32>
    // Divide by (H*W) = 100
    %hw_size = stablehlo.constant dense<100.0> : tensor<f32>
    %hw_size_bcast = "stablehlo.broadcast_in_dim"(%hw_size) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8xf32>
    %mean = stablehlo.divide %mean, %hw_size_bcast : tensor<8x8xf32>
    // Broadcast mean to [8,8,10,10]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<8x8xf32>) -> tensor<8x8x10x10xf32>
    // Subtract mean
    %centered = stablehlo.subtract %gelu, %mean_bcast : tensor<8x8x10x10xf32>
    // Compute variance: mean((x - mean)^2) over H,W
    %centered_sq = stablehlo.multiply %centered, %centered : tensor<8x8x10x10xf32>
    %var = "stablehlo.reduce"(%centered_sq, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2, 3>} : (tensor<8x8x10x10xf32>, tensor<f32>) -> tensor<8x8xf32>
    %var = stablehlo.divide %var, %hw_size_bcast : tensor<8x8xf32>
    // Broadcast var to [8,8,10,10]
    %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0,1>} : (tensor<8x8xf32>) -> tensor<8x8x10x10xf32>
    // Add epsilon (1e-5)
    %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %var_eps =

func.func @main(
