    // Compute x / sqrt(2)
    %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
    %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %x_div_sqrt2 = stablehlo.divide %conv_bias, %sqrt2_bcast : tensor<8x8x10x10xf32>
    %erf = "chlo.erf"(%x_div_sqrt2) : (tensor<8x8x10x10xf32>) -> tensor<8x8x10x10xf32>
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
    %erf_plus1 = stablehlo.add %erf, %one_bcast : tensor<8x8x10x10xf32>
    %half = stablehlo.constant dense<0.5> : tensor<f32>
    %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
