    // Compute mean over H,W (axes 2,3)
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %mean = "stablehlo.reduce"(%gelu, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2, 3>} : (tensor<8x8x10x10xf32>, tensor<f32>) -> tensor<8x8xf32>
    // Divide by (H*W) = 100
    %hw_size = stablehlo.constant dense<100.0> : tensor<f32>
    %hw_size_bcast = "stablehlo.broadcast_in_dim"(%hw_size) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8xf32>
