    %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0,1>} : (tensor<8x8xf32>) -> tensor<8x8x10x10xf32>
    // Add epsilon (1e-5)
    %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<8x8x10x10xf32>
