func.func @main(
  %multiply_weight: tensor<16xf32>, 
  %gemm_weight: tensor<16x16xf32>, 
  %gemm_bias: tensor<16xf32>, 
  %group_norm_weight: tensor<16xf32>, 
  %group_norm_bias: tensor<16xf32>, 
  %x: tensor<16x16xf32>
) -> tensor<16x16xf32> {
  // GEMM: y = x @ gemm_weight^T + gemm_bias
  // x: (16,16), gemm_weight: (16,16) (PyTorch: out_features x in_features)
  // dot_general: lhs=(16,16), rhs=(16,16), contract lhs[1] with rhs[1] (rhs must be transposed)
  %gemm_weight_T = "stablehlo.transpose"(%gemm_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %y_gemm = "stablehlo.dot_general"(%x, %gemm_weight_T) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: gemm_bias shape (16,) -> (1,16) -> (16,16)
  %gemm_bias_bcast = "stablehlo.broadcast_in_dim"(%gemm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %y_gemm_bias = stablehlo.add %y_gemm, %gemm_bias_bcast : tensor<16x16xf32>

  // GroupNorm: num_groups=16, num_channels=16, so each group is 1 channel
  // Per-group mean/var: reduce over axis 1 (channels)
  // mean = reduce_sum(x, axis=1) / 1 = x itself (since group size=1)
  // var = reduce_sum((x-mean)^2, axis=1) / 1 = 0 (since group size=1)
  // So, GroupNorm reduces to per-channel affine: y = x * weight + bias

  // But for completeness, let's compute mean and var as in general GroupNorm
  // Reshape to (N, num_groups, group_size) = (16,16,1)
  %y_gemm_bias_reshaped = stablehlo.reshape %y_gemm_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  // Compute mean over axis 2 (group_size)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%y_gemm_bias_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by group_size=1 (skip, as it's just itself)
  // Compute variance: mean((x - mean)^2, axis=2)
  // Broadcast mean to (16,16,1)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %y_centered = stablehlo.subtract %y_gemm_bias_reshaped, %mean_bcast : tensor<16x16x1xf32>
  %y_centered_sq = stablehlo.multiply %y_centered, %y_centered : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%y_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // Divide by group_size=1 (skip)
  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0000000116860974E-05> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %var_eps_bcast = "stablehlo.broadcast_in_dim"(%var_eps) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %std = stablehlo.sqrt %var_eps_bcast : tensor<16x16x1xf32>
  // Normalize: (x - mean) / std
  %y_norm = stablehlo.divide %y_centered, %std : tensor<16x16x1xf32>
  // Reshape back to (16,16)
  %y_norm_2d = stablehlo.reshape %y_norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>
  // Apply affine: y = y_norm * weight + bias
  // group_norm_weight, group_norm_bias: (16,) -> (1,16) -> (16,16)
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%group_norm_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%group_norm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %y_norm_affine = stablehlo.multiply %y_norm_2d, %gn_weight_bcast : tensor<16x16xf32>
  %y_norm_affine = stablehlo.add %y_norm_affine, %gn_bias_bcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_y = stablehlo.negate %y_norm_affine : tensor<16x16xf32>
  %exp_neg_y = stablehlo.exponential %neg_y : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %denom = stablehlo.add %one_bcast, %exp_neg_y : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
  %swish1 = stablehlo.multiply %y_norm_affine, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight: (16,) -> (1,16) -> (16,16)
  %mw_bcast = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %mul = stablehlo.multiply %swish1, %mw_bcast : tensor<16x16xf32>

  // Swish again: x * sigmoid(x)
  %neg_mul = stablehlo.negate %mul : tensor<16x16xf32>
  %exp_neg_mul = stablehlo.exponential %neg_mul : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_bcast, %exp_neg_mul : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
  %swish2 = stablehlo.multiply %mul, %sigmoid2 : tensor<16x16xf32>

  return %swish2 : tensor<16x16xf32>
}

func.func @main(
    %arg0: tensor<7x7xf32>,    // gemm.weight [out_features, in_features]
    %arg1: tensor<7xf32>,      // gemm.bias [out_features]
    %arg2: tensor<7xf32>,      // batch_norm.weight [out_features]
    %arg3: tensor<7xf32>,      // batch_norm.bias [out_features]
    %arg4: tensor<6x7xf32>     // input x [batch_size, in_features]
) -> tensor<6x7xf32> {
  // GEMM: y = x @ W^T + b
  // x: [6,7], W: [7,7] (out,in), so W^T: [7,7] -> [7,7] (symmetric)
  // dot_general: lhs [6,7], rhs [7,7], contract lhs:1, rhs:1
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Broadcast bias [7] to [6,7]
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // BatchNorm1d (training): y = (x - mean) / sqrt(var + eps) * weight + bias
  // Compute mean over batch (dim 0): shape [7]
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %3 = "stablehlo.reduce"(%2, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / batch_size
  %c6f = stablehlo.constant dense<6.0> : tensor<f32>
  %4 = stablehlo.divide %3, %c6f : tensor<7xf32>

  // Broadcast mean to [6,7]
  %5 = "stablehlo.broadcast_in_dim"(%4) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // x - mean
  %6 = stablehlo.subtract %2, %5 : tensor<6x7xf32>
  // (x - mean)^2
  %7 = stablehlo.multiply %6, %6 : tensor<6x7xf32>
  // variance: mean of squared deviations
  %8 = "stablehlo.reduce"(%7, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %9 = stablehlo.divide %8, %c6f : tensor<7xf32>
  // Add epsilon for numerical stability
  %ceps = stablehlo.constant dense<1.0000000116860974E-05> : tensor<f32>
  %10 = stablehlo.add %9, %ceps : tensor<7xf32>
  // sqrt(var + eps)
  %11 = stablehlo.sqrt %10 : tensor<7xf32>
  // Broadcast denominator to [6,7]
  %12 = "stablehlo.broadcast_in_dim"(%11) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  // Normalize: (x - mean) / sqrt(var + eps)
  %13 = stablehlo.divide %6, %12 : tensor<6x7xf32>
